// src/pages/HomePage.jsx
// Ten: Le Thanh Ho | MSSV: 2123110125 | Lop: CCQ2311D

import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import productService from "../services/productService";
import categoryService from "../services/categoryService";
import postService from "../services/postService";
import reviewService from "../services/reviewService";
import bannerService from "../services/bannerService"; // 🎯 BỔ SUNG: Import service gọi API Banner
import ProductCard from "../components/ProductCard";
import Loader from "../components/Loader";
import { resolveImageUrl } from "../components/ProductCard";

// 🎯 COMPONENT BANNER SLIDER ĐÃ ĐƯỢC CHUYỂN ĐỔI SANG ĐỘNG
function BannerSlider({ banners, loadingBanners }) {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (banners.length <= 1) return;
    const timer = setInterval(() => {
      setIndex((i) => (i + 1) % banners.length);
    }, 5000);
    return () => clearInterval(timer);
  }, [banners]);

  // Trạng thái chờ hoặc nếu Database chưa có banner nào
  if (loadingBanners) {
    return <div className="h-[400px] bg-ink flex items-center justify-center text-white/50"><Loader small /></div>;
  }

  if (banners.length === 0) {
    return (
      <section className="relative bg-ink text-white py-20 text-center">
        <p className="text-volt">Hệ thống xe đạp chính hãng BikeShop</p>
        <h1 className="font-display text-3xl mt-2">Chào mừng bạn đến với cửa hàng!</h1>
      </section>
    );
  }

  const slide = banners[index];

  return (
    <section className="relative bg-ink text-white overflow-hidden min-h-[420px] flex items-center">
      {/* 🎯 ĐÃ TÍCH HỢP: Ảnh nền Banner thực tế lấy trực tiếp từ database */}
      <div className="absolute inset-0 z-0">
        <img
          src={resolveImageUrl(slide.image)}
          alt={slide.title}
          className="w-full h-full object-cover opacity-30 transition-all duration-700 ease-in-out scale-105"
        />
        {/* Lớp phủ gradient giúp text chữ trắng nổi bật trên nền ảnh */}
        <div className="absolute inset-0 bg-gradient-to-r from-ink via-ink/80 to-transparent" />
      </div>

      {/* Hiệu ứng lưới sọc trang trí tinh tế */}
      <div
        className="absolute inset-0 opacity-10 z-10"
        style={{
          backgroundImage:
            "repeating-linear-gradient(115deg, transparent, transparent 60px, rgba(201,255,61,0.15) 60px, rgba(201,255,61,0.15) 62px)",
        }}
      />

      <div className="max-w-7xl mx-auto px-4 py-16 md:py-24 relative z-20 w-full">
        {/* Tận dụng trường title để hiển thị Tag nhỏ, hoặc hiển thị tên cửa hàng */}
        <p className="text-volt font-semibold tracking-widest text-sm mb-4 text-uppercase">
          <i className="fas fa-tags mr-1"></i> KHUYẾN MÃI HOT
        </p>
        <h1 className="font-display text-4xl md:text-5xl leading-tight max-w-2xl">
          {slide.title}
        </h1>

        {slide.link && (
          <Link
            to={slide.link}
            className="inline-block mt-8 bg-volt text-ink font-bold px-8 py-3 rounded-md hover:brightness-95 transition shadow-lg shadow-volt/20"
          >
            Khám phá ngay <i className="fas fa-arrow-right ml-1 text-xs"></i>
          </Link>
        )}

        {/* Các nút bấm chuyển slide tương ứng số lượng bản ghi DB */}
        {banners.length > 1 && (
          <div className="flex gap-2 mt-10">
            {banners.map((_, i) => (
              <button
                key={i}
                onClick={() => setIndex(i)}
                aria-label={`Slide ${i + 1}`}
                className={`h-1.5 rounded-full transition-all ${
                  i === index ? "bg-volt w-8" : "bg-white/30 w-4"
                }`}
              />
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

export default function HomePage() {
